// UpsertInstances inserts or overwrites several instance records of one
// service in a single transaction: any failure rolls the whole batch back,
// leaving no partial updates behind. Records are returned in input order.
func (s *Store) UpsertInstances(inputs []InstanceInput) ([]Instance, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return nil, err
	}
	defer tx.Rollback()

	statement, err := tx.Prepare(`...same upsert...`)
	if err != nil {
		return nil, err
	}
	defer statement.Close()

	for _, input := range inputs {
		heartbeat := input.HeartbeatAt.UTC().Format(time.RFC3339Nano)
		if _, err := statement.Exec(input.ServiceName, input.InstanceID, input.Address, input.Port, input.Healthy, input.Weight, heartbeat); err != nil {
			return nil, err
		}
	}
	if err := tx.Commit(); err != nil {
		return nil, err
	}

	instances := make([]Instance, 0, len(inputs))
	for _, input := range inputs {
		instances = append(instances, Instance{...from input...})
	}
	return instances, nil
}
```

